function formatDatatable(e,o,t){if(!$(e).length)return;const a="#"+e.replace("#","")+"buscador";$(a).val(""),$(e).DataTable().destroy();const n=$(e).DataTable({paging:!0,ordering:!0,info:!0,searching:!0,searchHighlight:!0,language:{sProcessing:"Procesando...",sLengthMenu:"Ver _MENU_",sZeroRecords:"No se encontraron resultados",sEmptyTable:"Sin Datos",sInfo:"_START_ al _END_ de _TOTAL_ registros",sInfoEmpty:"0",sInfoFiltered:"(total _MAX_ )",sLoadingRecords:"Cargando..."},order:[o,t]});$(".dataTables_filter").css("display","none"),$(".dt-search").css("display","none"),$(a).off("keyup").on("keyup",function(){n.search(this.value).draw()}),$(".dt-length").addClass("d-none");const s=document.querySelector("#table_wrapper .dt-layout-table").nextElementSibling;s.id="pagingFooter"}function exportToExcel(e,o){var t=XLSX.utils.book_new(),a=XLSX.utils.json_to_sheet(e);XLSX.utils.book_append_sheet(t,a,"Hoja 1"),XLSX.writeFile(t,o+".xlsx")}